# 4. ఉపన్యాస కళ (te4) – Telugu_01T.pdf పేజీలు 20–22
import os, sys
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..'))
from qbh import Bank, AR, PY, PV, NN, SD, SM, VY
B = Bank(4, 'te4'); q, m = B.q, B.mcq
PG = 'కింది పరిచిత గద్యం చదివి, ఇచ్చిన ప్రశ్నలకు జవాబులు రాయండి.\n'
q(1, 8, PG + 'కొందరు మంచి వక్త కావాలనే ఉబలాటంతో గొప్ప వక్తలను అనుకరిస్తారు. అందువల్ల ప్రయోజనం? అతడు గొంతెత్తగానే ఎవరిని అనుకరిస్తున్నాడో ప్రేక్షకులకు తెలిసిపోతుంది. అంతే సభలో కలకలం ప్రారంభం అవుతుంది. చౌకబారు అనుకరణలని నవ్వుకుంటారు. అసలు అసలే, నకిలీ నకిలీయే గదా? మనం మనంగా ఉన్నపుడే మనకు ప్రత్యేక స్థానం వుంటుంది. అత్యంత నైపుణ్యంతో చేయబడి అచ్చంగా గులాబిపువ్వే అనే భ్రమకలిగించే కాగితం పువ్వులో, గులాబీలో వుండే సుగంధాన్ని నింపగలమా? అందుకే అనుకరణ మంచిది కాదు.\nఅ) కొందరు మంచి వక్త కావాలనే ఉబలాటంతో ఏం చేస్తారు?\nఆ) మనకు ప్రత్యేక స్థానం ఎప్పుడు ఉంటుంది?\nఇ) కాగితం పువ్వులో దేనిని నింపలేము?\nఈ) గద్యం ఆధారంగా ఒక అర్థవంతమైన ప్రశ్న తయారుచేయండి.',
  'అ) గొప్ప వక్తలను అనుకరిస్తారు.\nఆ) మనం మనంగా ఉన్నప్పుడే (ఇతరులను అనుకరించనప్పుడే) మనకు ప్రత్యేక స్థానం ఉంటుంది.\nఇ) కాగితం పువ్వులో గులాబీలో ఉండే సుగంధాన్ని నింపలేము.\nఈ) అనుకరణ ఎందుకు మంచిది కాదు?')
q(1, 8, PG + 'కొందరికి కొన్ని ఊతపదాలు తరచుగా పడుతుంటాయి. ఆ విషయంలో వక్త జాగ్రత్తపడాలి. ఉదాహరణకు “అన్నమాట” అనే పదాన్ని చాలామంది ముఖ్యంగా స్త్రీలు తమ ఉపన్యాసాల్లో ఊతపదంగా వాడతారు. “నన్నేమో ఈ సభకు కార్యదర్శి, పిలవడానికి వచ్చాడన్నమాట. అప్పుడు నేను వేరే పనుల వత్తిడి వలన వెంటనే ఒప్పుకోలేదన్నమాట” అంటూ ప్రారంభిస్తారు. రెండు నిమిషాలు శ్రోతలు భరిస్తారు. ఆ తరువాత వాక్యం ముగియబోయేటప్పుడు “అన్నమాట” అంటూ శ్రోతలు కూడా ఊతం ఇస్తారు. దాంతో నవ్వులు – ఏకాగ్రత చెదిరిపోవడం – మధ్యలోనే ఉపన్యాసం ముగించడం జరుగుతుంది. మరికొన్ని ఊతపదాలు “ఇన్నింటికీ నేను చెప్పదల్చుకునేదేమంటే” “అంచేత” “అసలు విషయం” లాంటి ఊతపదాల అలవాటును అదుపులో పెట్టుకోవాలి.\nఅ) స్త్రీలు ఎక్కువగా వాడే ఊతపదమేది?\nఆ) ఊత పదాలను శ్రోతలు ఎంత సేపు భరిస్తారు?\nఇ) వక్త దేనిని అదుపులో పెట్టుకోవాలి?\nఈ) పై గద్యం ఆధారంగా ఒక అర్థవంతమైన ప్రశ్నను తయారు చేయండి.',
  'అ) “అన్నమాట”.\nఆ) రెండు నిమిషాలు భరిస్తారు.\nఇ) ఊతపదాలు వాడే అలవాటును అదుపులో పెట్టుకోవాలి.\nఈ) ఊతపదాలు ఎక్కువగా వాడితే ఉపన్యాసంలో ఏం జరుగుతుంది?')
q(1, 8, 'ఉపన్యాసంలో భాష ఎలా ఉంటే బాగుంటుంది? (ఉపన్యాస కళ ఆధారంగా)',
  '1) సరళ వ్యావహారిక భాష: శ్రోతలందరికీ అర్థమయ్యే సులభమైన, వాడుక భాషలో మాట్లాడాలి; కఠినమైన పండిత భాష, సంస్కృత సమాసాలు అతిగా వాడకూడదు.\n2) స్పష్టమైన ఉచ్చారణ: మాటలు స్పష్టంగా, సరైన వేగంతో పలకాలి; మధ్యమ స్వరంలో, సందర్భాన్ని బట్టి ఆరోహణ–అవరోహణలతో మాట్లాడాలి.\n3) ఊతపదాలు వద్దు: “అన్నమాట”, “అంచేత”, “అసలు విషయం” వంటి ఊతపదాలు శ్రోతల ఏకాగ్రతను చెడగొడతాయి.\n4) స్వోత్కర్ష వద్దు: తనను తాను పొగుడుకోవడం, ఇతరులను అతిగా పొగడడం మానాలి.\n5) సందర్భోచితం: సభ, శ్రోతల స్థాయికి తగిన భాష, ఉదాహరణలు, సామెతలు, చిన్న కథలు వాడితే ఉపన్యాసం ఆసక్తికరంగా ఉంటుంది.\n6) సంక్షిప్తత: అనవసర విషయాలు, పునరుక్తి లేకుండా విషయానికి కట్టుబడి మాట్లాడాలి.\n7) మర్యాదపూర్వకం: ఎవరినీ కించపరిచే మాటలు, అపహాస్యం ఉండకూడదు.\nముగింపు: సరళమైన, స్పష్టమైన, మర్యాదపూర్వకమైన భాషే శ్రోతల హృదయాలను గెలుస్తుంది.')
q(1, 8, 'మీ పాఠశాల విద్యార్థికి వక్తృత్వ పోటీలో జిల్లాస్థాయి బహుమతి వచ్చింది. అభినందిస్తూ అభినందన పత్రం రాయండి.',
  '🌸 అభినందన పత్రం 🌸\nజిల్లా పరిషత్ ఉన్నత పాఠశాల, టి.వి. పల్లి, గూడూరు మండలం, SPSR నెల్లూరు జిల్లా\nచిరంజీవి కుమారి కె. లక్ష్మి, 10వ తరగతి –\nనెల్లూరులో xx-xx-20xx న జరిగిన జిల్లాస్థాయి వక్తృత్వ పోటీలో “విద్యార్థులు – సామాజిక బాధ్యత” అంశంపై అద్భుతంగా ప్రసంగించి ప్రథమ బహుమతి సాధించినందుకు మా హృదయపూర్వక అభినందనలు.\n• నీ స్పష్టమైన ఉచ్చారణ, సరళమైన భాష, చక్కని ఉదాహరణలు, ఆత్మవిశ్వాసం న్యాయనిర్ణేతలను, శ్రోతలను ఆకట్టుకున్నాయి.\n• నీ విజయం మన పాఠశాలకు, మన మండలానికి గర్వకారణం; తోటి విద్యార్థులకు స్ఫూర్తి.\n• ఇదే పట్టుదలతో రాష్ట్ర, జాతీయ స్థాయిల్లో కూడా విజయాలు సాధించాలని ఆశిస్తున్నాం.\nనీ భవిష్యత్తు ఉజ్జ్వలంగా ఉండాలని ఆకాంక్షిస్తూ –\nప్రధానోపాధ్యాయులు, ఉపాధ్యాయ బృందం, విద్యార్థులు.\nతేదీ: xx-xx-20xx.')
q(1, 4, 'వ్యాసం ప్రక్రియను వివరించండి.',
  '• వ్యాసం ఆధునిక వచన ప్రక్రియ; ఆంగ్లంలోని ‘Essay’కి సమానం.\n• ఒక విషయాన్ని తీసుకొని దానిని పూర్వాపరాలతో, సమగ్రంగా విశ్లేషిస్తూ రాయడం వ్యాసం.\n• దీనికి ఉపోద్ఘాతం (ప్రారంభం), విషయ విస్తరణ, ముగింపు (ఉపసంహారం) అనే మూడు ప్రధాన భాగాలు ఉంటాయి.\n• తార్కికత, స్పష్టత, ఉదాహరణలు, రచయిత అభిప్రాయం వ్యాస లక్షణాలు.\n• “ఉపన్యాస కళ” పాఠం వాసిరెడ్డి సీతాదేవి రాసిన వ్యాసం.')
m(1, 'ఎవరినీ అపహాస్యం చేయకూడదు. (గీత గీసిన పదం: అపహాస్యం) సరైన అర్థం గుర్తించండి.', ['హాస్యం', 'ఆక్రోశం', 'చిరునవ్వు', 'ఎగతాళి'], 3, mk=2)
m(1, 'విద్యార్థులు శబ్దకోశం వినియోగించాలి. (గీత గీసిన పదం: శబ్దకోశం) సరైన అర్థం గుర్తించండి.', ['నిఘంటువు', 'పుస్తకము', 'నవల', 'నాటకము'], 0, mk=2)
for w, a in [('సానపట్టు', 'పదును పెట్టు, మెరుగుపరచు'), ('ఆసీనులగు', 'కూర్చొను')]:
    q(1, 2, f'‘{w}’ {AR}', a)
m(1, 'వక్త వేదికమీద హుందాగా ప్రవర్తించాలి. (గీత గీసిన పదం: వక్త) పర్యాయపదాలు గుర్తించండి.', ['వ్యక్తి, మనిషి', 'ఉపన్యాసకుడు, వంచకుడు', 'మాటకారి, ఉపన్యాసకుడు', 'మాటకారి, సంస్కర్త'], 2, mk=2)
m(1, 'శివుడు కుత్తుకలో విషం దాచుకున్నాడు. (గీత గీసిన పదం: కుత్తుక) సరైన పర్యాయపదాలు గుర్తించండి.', ['అరుగు, తిన్నె', 'గొంతు, కంఠం', 'నీళ్ళు, సలిలము', 'నెయ్యి, ఘృతము'], 1, mk=2)
for w, a in [('మనీషి', 'జ్ఞాని, పండితుడు, బుద్ధిమంతుడు, విద్వాంసుడు'), ('వేదిక', 'అరుగు, తిన్నె, వేది')]:
    q(1, 2, f'‘{w}’ {PY}', a)
m(1, 'విద్యార్థులు ఉన్నతోన్నత శిఖరాలు అధిరోహించాలి. (గీత గీసిన పదం: ఉన్నతోన్నత) విడదీసి గుర్తించండి.', ['ఉన్నతో + ఉన్నత', 'ఉన్నతా + ఉన్నతా', 'ఉన్నత + ఉన్నతి', 'ఉన్నత + ఉన్నత'], 3, 'గుణ సంధి (అ + ఉ = ఓ).')
m(1, 'కింది పదాలలో అత్వసంధికి చెందిన పదాన్ని గుర్తించండి.', ['కదిలినప్పుడు', 'అప్పుడప్పుడు', 'సోముడితడు', 'అనురాగమంత'], 0, 'కదిలిన + అప్పుడు = కదిలినప్పుడు – అత్వ సంధి.')
m(1, 'మీకు తెలిసినవారు ఎవరన్నారు. (గీత గీసిన పదం: ఎవరన్నారు) ఏ సంధి?', ['ఉత్వసంధి', 'అత్వసంధి', 'ఇత్వసంధి', 'రుగాగమ సంధి'], 0, 'ఎవరు + అన్నారు – ఉత్వ సంధి.')
for w, a in [('స్వోత్కర్ష', 'స్వ + ఉత్కర్ష – గుణ సంధి'), ('మహోత్కృష్ట', 'మహా + ఉత్కృష్ట – గుణ సంధి'), ('పొందాలనుకుంటారు', 'పొందాలి + అనుకుంటారు – ఇత్వ సంధి'), ('ఉత్తమమైనది', 'ఉత్తమము + ఐనది – ఉత్వ సంధి')]:
    q(1, 1, f'‘{w}’ {SD}', a)
m(1, 'సమయసందర్భాలను గురించి మాట్లాడాలి. (గీత గీసిన పదం: సమయసందర్భాలు) విగ్రహవాక్యం గుర్తించండి.', ['సమయము యొక్క సందర్భం', 'సమయమును, సందర్భమును', 'సమయానికి సందర్భం', 'సమయమైన సందర్భం'], 1, 'ద్వంద్వ సమాసం.')
m(1, 'గులాబీపువ్వు సువాసనాభరితముగా ఉంటుంది. (గీత గీసిన పదం: గులాబీపువ్వు) ఏ సమాసం?', ['విశేషణ పూర్వపద కర్మధారయ సమాసం', 'సంభావనా పూర్వపద కర్మధారయ సమాసం', 'చతుర్థీ తత్పురుష సమాసం', 'ఉపమాన పూర్వపద కర్మధారయ సమాసం'], 1, 'గులాబీ అను పేరు గల పువ్వు – సంభావనా పూర్వపద కర్మధారయం.')
for w, a in [('శబ్దశక్తి', 'శబ్దము యొక్క శక్తి – షష్ఠీ తత్పురుష సమాసం'), ('కార్యక్షేత్రం', 'కార్యము యొక్క క్షేత్రం – షష్ఠీ తత్పురుష సమాసం'), ('రెండునిమిషాలు', 'రెండు సంఖ్య గల నిమిషాలు – ద్విగు సమాసం'), ('సభాకంపం', 'సభ వలన కంపం – పంచమీ తత్పురుష సమాసం')]:
    q(1, 1, f'‘{w}’ {SM}', a)
for s, a in [('అలవాటును అదుపులో పెట్టుకోవాలి.', 'విధ్యర్థక వాక్యం (కర్తవ్యాన్ని తెలిపేది)'), ('నేను వేదిక మీద ఎలా ప్రవర్తించాను?', 'ప్రశ్నార్థక వాక్యం'), ('మాట్లాడిన వక్త అభిమానులు ఇక్కడ ఉండవచ్చునేమో.', 'సందేహార్థక వాక్యం'), ('అది ప్రయత్నిస్తే వచ్చేది కాదా?', 'ప్రశ్నార్థక వాక్యం')]:
    q(1, 1, f'ఇది ఏ రకమైన సామాన్య వాక్యమో రాయండి: “{s}”', a)
q(1, 1, '“సందేహార్థక వాక్యం”నకు ఒక ఉదాహరణ రాయండి.', 'ఈరోజు సాయంత్రం వర్షం పడుతుందేమో. (సందేహాన్ని తెలిపే వాక్యం)')
# ══ LEVEL-2 ══
q(2, 8, 'మంచి వక్తగా ఎదగాలంటే ఏం చేయాలో “ఉపన్యాస కళ” పాఠం ఆధారంగా రాయండి.',
  '1) సాధన: వక్తృత్వం పుట్టుకతో వచ్చే వరం కాదు; కృషి, సాధన, పట్టుదల ఉంటే ఎవరైనా వక్త కావచ్చు – చర్చిల్ అద్దం ముందు అభ్యాసం చేసి మహావక్త అయ్యాడు.\n2) అనుకరణ వద్దు: ఇతరులను అనుకరిస్తే కాగితం పువ్వులా సువాసన ఉండదు; మనం మనంగా ఉండాలి.\n3) సభాకంపాన్ని జయించాలి: భయం సహజం; సిద్ధతతో, ఆత్మవిశ్వాసంతో దానిని అధిగమించాలి.\n4) వేదిక మర్యాద: హుందాగా కూర్చోవాలి, సందర్భానికి తగిన దుస్తులు; మైకు ముందు రిలాక్స్‌గా నిలబడాలి; ఊగడం, నేలచూపులు, ఆవలింతలు, కాలుపై కాలు వేయడం మానాలి.\n5) ప్రసంగ నిర్మాణం: ప్రారంభం (క్షణం మౌనం, చిరునవ్వుతో), విషయ ప్రతిపాదన (స్పష్టమైన వాచకం, ఆరోహణ–అవరోహణలు), ఉపసంహారం – శ్రోతల ఆసక్తి తగ్గకముందే ముగించాలి.\n6) భాష: సరళ వ్యావహారిక భాష; ఊతపదాలు, స్వోత్కర్ష, అతిశయోక్తులు వద్దు.\n7) విషయ సేకరణ: విస్తృతంగా చదవాలి; ఉదాహరణలు, సూక్తులు సేకరించాలి.\n8) ఆత్మపరిశీలన: ఉపన్యాసం తర్వాత లోపాలు గుర్తించి సరిదిద్దుకోవాలి.')
q(2, 8, 'స్వాతంత్ర్య దినోత్సవ సందర్భంగా మిమ్మల్ని ఉపన్యాసం ఇవ్వమని అడిగారు. ఆ ఉపన్యాస ప్రతిని ఎలా సిద్ధం చేస్తారో తెలపండి.',
  'సిద్ధత: స్వాతంత్ర్య పోరాట చరిత్ర, నాయకుల త్యాగాలు, నేటి భారత ప్రగతి గురించి సమాచారం సేకరిస్తాను. ప్రారంభం, విషయం, ముగింపు అని మూడు భాగాలుగా రాసుకుని అద్దం ముందు అభ్యాసం చేస్తాను.\nఉపన్యాస ప్రతి:\nగౌరవనీయులైన ప్రధానోపాధ్యాయులకు, ఉపాధ్యాయులకు, నా ప్రియమైన మిత్రులకు నమస్కారం. ఈరోజు మనం 79వ స్వాతంత్ర్య దినోత్సవాన్ని ఆనందంగా జరుపుకుంటున్నాం.\nదాదాపు రెండు వందల ఏళ్ళ బ్రిటిష్ పాలన నుండి మన దేశానికి 1947 ఆగస్టు 15న స్వాతంత్ర్యం వచ్చింది. ఈ స్వేచ్ఛ కోసం మహాత్మా గాంధీ అహింసా మార్గంలో పోరాడారు; భగత్‌సింగ్, అల్లూరి సీతారామరాజు, సుభాష్ చంద్రబోస్ వంటి వీరులు ప్రాణాలర్పించారు; పొట్టి శ్రీరాములు, టంగుటూరి ప్రకాశం వంటి తెలుగు నాయకులూ పాల్గొన్నారు.\nనేడు భారత్ విజ్ఞాన శాస్త్రం, సాంకేతికత, అంతరిక్ష పరిశోధనల్లో ప్రపంచానికి ఆదర్శంగా నిలుస్తోంది. కానీ పేదరికం, నిరక్షరాస్యత, అవినీతి, కాలుష్యం వంటి సమస్యలను విద్యార్థులమైన మనం బాగా చదివి, క్రమశిక్షణతో, దేశభక్తితో పరిష్కరించాలి.\nమన త్యాగధనుల ఆశయాలను నెరవేర్చడమే వారికి నిజమైన నివాళి. జై హింద్! భారత్ మాతా కీ జై!\nధన్యవాదాలు.')
for w, a in [('క్రొమ్మావి', 'క్రొత్త + మావి – ప్రాతాది సంధి'), ('ముంజేయి', 'ముందు + చేయి – ప్రాతాది సంధి'), ('మున్నుడి', 'మును + నుడి – ప్రాతాది సంధి'), ('లేమొగ్గ', 'లేత + మొగ్గ – ప్రాతాది సంధి')]:
    q(2, 1, f'‘{w}’ {SD}', a)
for w, a in [('ప్రజాహితం', 'ప్రజల యొక్క హితం – షష్ఠీ తత్పురుష సమాసం'), ('ప్రసన్నవదనం', 'ప్రసన్నమైన వదనం – విశేషణ పూర్వపద కర్మధారయ సమాసం'), ('కవితాచరణం', 'కవిత యొక్క చరణం – షష్ఠీ తత్పురుష సమాసం'), ('వింతచప్పుడు', 'వింతైన చప్పుడు – విశేషణ పూర్వపద కర్మధారయ సమాసం')]:
    q(2, 1, f'‘{w}’ {SM}', a)
ITEMS = B.items
